package net.officefloor.hq.app.claim;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The people's claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /**
     * A claim as shown: the amount with two decimals, the date as yyyy-mm-dd, and the due fixed when it was
     * settled (null when it has none, so its due is worked out from the current rate), and who opened it;
     * whether the person's last statement bound it, and the due it bound it to (null: none, so n/a); and the number of
     * the claim it corrects (null unless it is a correction); and the date that decides how its live figures round (its
     * own, or a correction's corrected claim's); and its place in its person's list (a later place listed first); and
     * its status log, oldest first; and the date it is deferred until (null when never deferred); and how many proofs
     * it has; and the number of the claim it was split off (null unless it was); and the user whose open editor locks
     * it (null when not locked); and the last day it was reminded (null when never); and its external reference (null
     * when it has none); and its tags, sorted and comma separated (null when it has none); and the reason it was voided
     * with (null when none).
     */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
            LocalDate roundingDate, long listed, LocalDate dueBy, List<ClaimLogView> log, LocalDate deferredUntil,
            int proofs, String splitFrom, String lockedBy, boolean lateEntry, LocalDate remindedOn, String ref,
            String tags, String voidReason) {

        static ClaimView of(Claim claim, List<ClaimLog> log) {
            return new ClaimView(claim.getId(), claim.getPersonId(),
                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    claim.getDate(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                    claim.getOpenedBy(), claim.isStated(),
                    claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                    claim.getCorrects(), claim.getRoundingDate(), claim.getListed(), claim.getDueBy(),
                    log.stream().map(ClaimLogView::of).toList(), claim.getDeferredUntil(),
                    claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(),
                    claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(),
                    claim.getTags(), claim.getVoidReason());
        }
    }

    /** A line of a claim's status log: the status, who changed it, the sheet's today then, and its due then (or n/a). */
    public record ClaimLogView(ClaimStatus status, String by, LocalDate date, String due) {

        static ClaimLogView of(ClaimLog line) {
            return new ClaimLogView(line.getStatus(), line.getBy(), line.getDate(), line.getDue());
        }
    }

    /**
     * An amount with up to two decimals, negative only for a correction; a missing date takes the sheet's today; the
     * number of the claim a correction corrects, blank for any other claim; an external reference, blank for none;
     * comma separated tags, blank for none.
     */
    public record ClaimRequest(
            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
            LocalDate date,
            @Size(max = 1000) String note,
            @Size(max = 255) String corrects,
            @Size(max = 255) String ref,
            @Size(max = 1000) String tags) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }

        String correctsValue() {
            if (corrects == null || corrects.isBlank()) {
                return null;
            }
            // A sheet-wide number is written without leading zeros; a period number (P1-1, X-1) as typed.
            String trimmed = corrects.trim();
            return trimmed.matches("\\d{1,18}") ? String.valueOf(Long.parseLong(trimmed)) : trimmed;
        }
    }

    /** The ids of the claims selected to open together. */
    public record BulkOpenRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
    }

    /** The ids of the claims selected to settle together. */
    public record BulkSettleRequest(@NotNull @Size(max = 10000) List<@NotNull Long> ids) {
    }

    /** Lines of name,amount,date,note to add as DRAFT claims. */
    public record PasteRequest(@NotNull @Size(max = 1000000) String text) {
    }

    /** How many claims a paste added. */
    public record PasteResult(int added) {
    }

    private final ClaimService service;
    private final BulkOpenService bulkOpen;
    private final BulkSettleService bulkSettle;
    private final PasteClaimsService paste;

    public ClaimController(ClaimService service, BulkOpenService bulkOpen, BulkSettleService bulkSettle,
            PasteClaimsService paste) {
        this.service = service;
        this.bulkOpen = bulkOpen;
        this.bulkSettle = bulkSettle;
        this.paste = paste;
    }

    /** All the sheet's claims, newest first. */
    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        Map<Long, List<ClaimLog>> logs = service.logs(sheetId.trim());
        return service.list(sheetId.trim()).stream()
                .map(claim -> ClaimView.of(claim, logs.getOrDefault(claim.getId(), List.of())))
                .toList();
    }

    /** Every tag ever used on the sheet, sorted. */
    @GetMapping("/claims/tags")
    public List<String> tags(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.tags(sheetId.trim());
    }

    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return view(service.add(sheetId.trim(), user.trim(), personId, request.amountValue(), request.date(),
                request.note(), request.correctsValue(), request.ref(), request.tags()));
    }

    /** Add a DRAFT claim per pasted line, in order; refused as a whole when any line would be. */
    @PostMapping("/claims/paste")
    public PasteResult paste(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid PasteRequest request) {
        return new PasteResult(paste.paste(sheetId.trim(), user.trim(), request.text()));
    }

    /** Edit a DRAFT claim; refused for any other status. */
    @PutMapping("/claims/{id}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return view(service.update(sheetId.trim(), user.trim(), id, request.amountValue(), request.date(),
                request.note(), request.correctsValue(), request.ref(), request.tags()));
    }

    /** Open the claim's editor, locking it against other users' edits; refused for a claim that cannot be edited. */
    @PostMapping("/claims/{id}/lock")
    public ClaimView lock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.lock(sheetId.trim(), user.trim(), id));
    }

    /** Cancel the user's editor of the claim, releasing its lock. */
    @PostMapping("/claims/{id}/unlock")
    public ClaimView unlock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.unlock(sheetId.trim(), user.trim(), id));
    }

    /** Open a DRAFT claim. */
    @PostMapping("/claims/{id}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.OPEN));
    }

    /** Open the selected claims in list order; each one that cannot be opened is left as it is. */
    @PostMapping("/claims/bulk-open")
    public BulkOpenService.Result bulkOpen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkOpenRequest request) {
        return bulkOpen.open(sheetId.trim(), user.trim(), request.ids());
    }

    /** Settle the selected claims in list order; each one that cannot be settled is left as it is. */
    @PostMapping("/claims/bulk-settle")
    public BulkSettleService.Result bulkSettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid BulkSettleRequest request) {
        return bulkSettle.settle(sheetId.trim(), user.trim(), request.ids());
    }

    /** Settle an OPEN claim; refused to the user who opened it; PENDING instead when a clerk settles it above the clerk limit. */
    @PostMapping("/claims/{id}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.SETTLED));
    }

    /** Re-settle a SETTLED claim at its figure as of today: a steward only. */
    @PostMapping("/claims/{id}/resettle")
    public ClaimView resettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.resettle(sheetId.trim(), user.trim(), id));
    }

    /** A steward's reason for rejecting a PENDING claim. */
    public record RejectRequest(@NotBlank @Size(max = 1000) String reason) {
    }

    /** Approve a PENDING claim: a steward only, and not the one who opened it. */
    @PostMapping("/claims/{id}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.approve(sheetId.trim(), user.trim(), id));
    }

    /** Reject a PENDING claim with a reason, back to OPEN: a steward only. */
    @PostMapping("/claims/{id}/reject")
    public ClaimView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RejectRequest request) {
        // One line in the audit file: any run of white space in the reason becomes a single space.
        String reason = request.reason().trim().replaceAll("\\s+", " ");
        return view(service.reject(sheetId.trim(), user.trim(), id, reason));
    }

    /** The person a claim is moved to. */
    public record ReassignRequest(@NotNull Long personId) {
    }

    /** Move a DRAFT, OPEN or PENDING claim to another person: a role the permission matrix allows to reassign. */
    @PostMapping("/claims/{id}/reassign")
    public ClaimView reassign(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ReassignRequest request) {
        return view(service.reassign(sheetId.trim(), user.trim(), id, request.personId()));
    }

    /** The date an OPEN claim is deferred until; it must be after the sheet's today. */
    public record DeferRequest(@NotNull LocalDate until) {
    }

    /** Defer an OPEN claim until a date after the sheet's today. */
    @PostMapping("/claims/{id}/defer")
    public ClaimView defer(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid DeferRequest request) {
        return view(service.defer(sheetId.trim(), user.trim(), id, request.until()));
    }

    /** The new date of a claim re-dated. */
    public record RedateRequest(@NotNull LocalDate date) {
    }

    /** Re-date an OPEN or PENDING claim: a steward only. */
    @PostMapping("/claims/{id}/redate")
    public ClaimView redate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RedateRequest request) {
        return view(service.redate(sheetId.trim(), user.trim(), id, request.date()));
    }

    /** The amount split off a claim: more than 0.00 and less than the claim's amount. */
    public record SplitRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String amount) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2, RoundingMode.UNNECESSARY);
        }
    }

    /** Split an amount off an OPEN claim into a new OPEN claim of the same person: the new claim. */
    @PostMapping("/claims/{id}/split")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView split(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid SplitRequest request) {
        return view(service.split(sheetId.trim(), user.trim(), id, request.amountValue()));
    }

    /** Add a proof to a claim, raising its proofs count by one; refused for a SETTLED or VOID claim. */
    @PostMapping("/claims/{id}/proof")
    public ClaimView addProof(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.addProof(sheetId.trim(), user.trim(), id));
    }

    /** Remind an OPEN or PENDING claim, at most once per sheet-today. */
    @PostMapping("/claims/{id}/remind")
    public ClaimView remind(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.remind(sheetId.trim(), user.trim(), id));
    }

    /** The reason a claim is voided with, from the sheet's list of void reasons; blank or missing for none. */
    public record VoidRequest(@Size(max = 255) String reason) {
    }

    /**
     * Void a DRAFT, OPEN or PENDING claim, or (a steward, within 7 days of its settlement) a SETTLED one; while the
     * sheet has void reasons, with one of them.
     */
    @PostMapping("/claims/{id}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) @Valid VoidRequest request) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), id, ClaimStatus.VOID,
                request == null ? null : request.reason()));
    }

    /** The claim as shown, with its status log. */
    ClaimView view(Claim claim) {
        return ClaimView.of(claim, service.logOf(claim));
    }
}

package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** One line of a claim's status log: a status it took, who changed it, the sheet's today then, and its due then. */
@Entity
@Table(name = "claim_log")
public class ClaimLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "by_user", nullable = false)
    private String by;

    @Column(name = "logged_on", nullable = false)
    private LocalDate date;

    /** The claim's due at that moment, two decimals, or n/a. */
    @Column(name = "due", nullable = false)
    private String due;

    protected ClaimLog() {
    }

    public ClaimLog(String sheetId, Long claimId, ClaimStatus status, String by, LocalDate date, String due) {
        this.sheetId = sheetId;
        this.claimId = claimId;
        this.status = status;
        this.by = by;
        this.date = date;
        this.due = due;
    }

    public Long getId() {
        return id;
    }

    public Long getClaimId() {
        return claimId;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getBy() {
        return by;
    }

    public LocalDate getDate() {
        return date;
    }

    public String getDue() {
        return due;
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ClaimLogRepository extends JpaRepository<ClaimLog, Long> {

    /** A sheet's claim log lines, oldest first. */
    List<ClaimLog> findBySheetIdOrderByIdAsc(String sheetId);

    /** A claim's log lines, oldest first. */
    List<ClaimLog> findByClaimIdOrderByIdAsc(Long claimId);
}
-- A claim's status log: one line per status it has had, in the order of their ids. Each keeps who made the change,
-- the sheet's today then, and the claim's due as it was computed at that moment (two decimals, or n/a).
CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT       NOT NULL REFERENCES claim (id),
    status    VARCHAR(10)  NOT NULL,
    by_user   VARCHAR(100) NOT NULL,
    logged_on DATE         NOT NULL,
    due       VARCHAR(20)  NOT NULL
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, id);
package net.officefloor.hq.app.claim;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A proof added to a claim that does not take one, or a claim settled or approved without the proof it needs. */
@ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)
public class ClaimProofException extends RuntimeException {

    public ClaimProofException(Long id, String why) {
        super("Claim " + id + ": " + why);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayService;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.WatchService;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateService;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.voidreason.VoidReason;
import net.officefloor.hq.app.voidreason.VoidReasonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the people's claims on a sheet. A new claim with no date is dated the sheet's entry date while it is set, else
 * the sheet's today; an edited one with no date the sheet's today. A claim belongs to the period its due-by (fixed when
 * it is added) falls in; one whose due-by is in a closed period cannot be added, edited, deferred or change status. Only a DRAFT claim can be edited; a PENDING claim, waiting for a
 * steward to approve or reject it, is otherwise handled like an OPEN one. No claim
 * can be dated after the retirement date of its person. A claim whose due is above the proof threshold on its date
 * cannot be settled or approved without a proof; one whose due is above the note threshold on its date cannot be
 * opened with an empty note. A claim with a negative amount is a correction: it must name,
 * by number, a SETTLED claim of the same person that it corrects, and its due has no floor and no late charge.
 */
@Service
public class ClaimService {

    /** The days after its settlement within which a steward may still void a SETTLED claim. */
    private static final int SETTLED_VOID_DAYS = 7;

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final RateService rates;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final PeriodService periods;
    private final RoleService roles;
    private final SettingService settings;
    private final ClaimLogRepository logs;
    private final WatchService watches;
    private final HolidayService holidays;
    private final SheetTagRepository tags;
    private final VoidReasonService voidReasons;

    public ClaimService(ClaimRepository claims, PersonRepository people, RateService rates, SheetService sheets,
            Audit audit, RollupService rollup, PeriodService periods, RoleService roles, SettingService settings,
            ClaimLogRepository logs, WatchService watches, HolidayService holidays, SheetTagRepository tags,
            VoidReasonService voidReasons) {
        this.voidReasons = voidReasons;
        this.tags = tags;
        this.holidays = holidays;
        this.logs = logs;
        this.watches = watches;
        this.periods = periods;
        this.roles = roles;
        this.settings = settings;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /** Every tag ever used on the sheet, sorted. */
    public List<String> tags(String sheetId) {
        return tags.findBySheetIdOrderByTagAsc(sheetId).stream().map(SheetTag::getTag).toList();
    }

    /** The status logs of the sheet's claims by claim id, each oldest first. */
    public Map<Long, List<ClaimLog>> logs(String sheetId) {
        return logs.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(ClaimLog::getClaimId, Collectors.toList()));
    }

    /** The claim's status log, oldest first. */
    public List<ClaimLog> logOf(Claim claim) {
        return logs.findByClaimIdOrderByIdAsc(claim.getId());
    }

    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(sheetId, user, personId, amount, date, note, corrects, null);
    }

    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
    }

    /**
     * Adds a claim with an external reference (blank: none), refused when the reference is already used on the sheet,
     * and comma separated tags (blank: none).
     */
    @Transactional
    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tagText) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
        // Due by its person's terms on its date in business days after it, skipping the sheet's holidays now, fixed from now on;
        // its period is the one of its due-by.
        LocalDate dueBy = dueByOf(sheetId, person, dated);
        periods.requireOpen(sheetId, dueBy);
        person.requireClaimable(dated);
        LocalDate correctedDate = requireCorrection(sheetId, personId, amount, corrects);
        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note));
        claim.setCorrects(corrects);
        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
        claim.setDueBy(dueBy);
        // Taking the next list place locks the sheet, so two adds of the same reference do not both pass the check.
        claim.setListed(sheets.nextListed(sheetId));
        String reference = refOf(ref);
        if (reference != null && claims.existsBySheetIdAndRefIgnoreCase(sheetId, reference)) {
            throw new ClaimRefException(reference);
        }
        claim.setRef(reference);
        claim.setTags(tagged(sheetId, tagText));
        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved)
                + (saved.getRef() == null ? "" : " ref=" + saved.getRef())
                + (saved.getTags() == null ? "" : " tags=" + saved.getTags()));
        if (saved.isLateEntry()) {
            audit.recordOnCommit(record("LATE_ENTRY", user, person, saved));
        }
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    @Transactional
    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tagText) {
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimNotEditableException(id, claim.getStatus());
        }
        // Not while another user has its editor open.
        if (claim.isLockedAgainst(user)) {
            throw new ClaimLockedException(id, claim.getLockedBy());
        }
        LocalDate dated = dateOr(sheetId, date);
        // Its due-by, and so its period, stays as fixed when it was added.
        periods.requireOpen(sheetId, claim.getDueBy());
        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
                .requireClaimable(dated);
        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
        String reference = refOf(ref);
        if (reference != null && claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, reference, id)) {
            throw new ClaimRefException(reference);
        }
        claim.setRef(reference);
        claim.setTags(tagged(sheetId, tagText));
        claim.setAmount(amount);
        claim.setCorrects(corrects);
        claim.setDate(dated);
        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
        claim.setNote(noteOf(note));
        // Saving the editor releases its lock.
        claim.setLockedBy(null);
        Claim saved = claims.saveAndFlush(claim);
        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Open the claim's editor for the user, locking the claim against other users' edits until it is saved or
     * cancelled, or the sheet's today changes. Refused, taking no lock, for a claim that cannot be edited: not a DRAFT,
     * due by a date in a closed period, or locked by another user. The user's own lock is taken again.
     */
    @Transactional
    public Claim lock(String sheetId, String user, Long id) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ClaimNotEditableException(id, claim.getStatus());
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        if (claim.isLockedAgainst(user)) {
            throw new ClaimLockedException(id, claim.getLockedBy());
        }
        claim.setLockedBy(user);
        return claims.saveAndFlush(claim);
    }

    /** Cancel the user's editor of the claim, releasing its lock; another user's lock is left as it is. */
    @Transactional
    public Claim unlock(String sheetId, String user, Long id) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (user.equals(claim.getLockedBy())) {
            claim.setLockedBy(null);
            return claims.saveAndFlush(claim);
        }
        return claim;
    }

    /**
     * Move a claim to another status, if its current one allows it; refused otherwise. A clerk settling a claim whose
     * due is above the clerk limit sends it to PENDING instead, for a steward to approve or reject.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status) {
        return changeStatus(sheetId, user, id, status, null);
    }

    /**
     * Move a claim to another status, as {@link #changeStatus(String, String, Long, ClaimStatus)}. While the sheet's
     * list of void reasons is not empty, a void needs a reason from it; the claim keeps the reason it was voided with.
     */
    @Transactional
    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status, String voidReason) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        boolean voidsSettled = status == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
        if (!voidsSettled && (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING)) {
            throw new ClaimStatusException(id, claim.getStatus(), status);
        }
        // The sheet's permission matrix decides which roles may open, settle or void.
        String action = switch (status) {
            case OPEN -> "open";
            case SETTLED -> "settle";
            case VOID -> "void";
            case DRAFT, PENDING -> throw new ClaimStatusException(id, claim.getStatus(), status);
        };
        if (!roles.may(sheetId, user, action)) {
            throw new ClaimActionForbiddenException(id, user, action);
        }
        if (voidsSettled) {
            requireSettledVoidable(sheetId, user, claim);
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        String reason = status == ClaimStatus.VOID ? requireVoidReason(sheetId, id, voidReason) : null;
        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
        if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
            throw new ClaimDeferException(id, "it is deferred until " + claim.getDeferredUntil());
        }
        // Four eyes: whoever opened a claim cannot also settle it.
        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ClaimSettledByOpenerException(id, user);
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        if (status == ClaimStatus.SETTLED) {
            requireProof(sheetId, person, claim);
        }
        if (status == ClaimStatus.OPEN) {
            requireNote(sheetId, person, claim);
        }
        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
            BigDecimal limit = settings.get(sheetId).getClerkLimit();
            BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                status = ClaimStatus.PENDING;
            }
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
        claim.setStatus(status);
        if (status == ClaimStatus.VOID) {
            claim.setVoidReason(reason);
        }
        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
        String number = claim.getNumber();
        if (status == ClaimStatus.OPEN) {
            number = nextNumber(sheetId, claim.getDueBy());
            claim.setNumber(number);
            claim.setOpenedBy(user);
        }
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        String event = switch (status) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException();
        };
        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due
                + (reason == null ? "" : " reason=" + reason));
        if (status == ClaimStatus.SETTLED) {
            watches.notifyWatchers(sheetId, user, person, number);
        }
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * The reason a claim is voided with: none while the sheet's list of void reasons is empty, else the one given,
     * which must be on the list.
     */
    private String requireVoidReason(String sheetId, Long id, String given) {
        List<String> listed = voidReasons.list(sheetId).stream().map(VoidReason::getReason).toList();
        if (listed.isEmpty()) {
            return null;
        }
        String reason = given == null ? "" : given.trim();
        if (reason.isEmpty()) {
            throw new ClaimVoidReasonException(id, "choose a reason from the sheet's void reasons");
        }
        if (!listed.contains(reason)) {
            throw new ClaimVoidReasonException(id, reason + " is not one of the sheet's void reasons");
        }
        return reason;
    }

    /**
     * A steward other than its opener approves a PENDING claim: it becomes SETTLED, its due frozen at that moment from
     * its live figure.
     */
    @Transactional
    public Claim approve(String sheetId, String user, Long id) {
        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.SETTLED);
        if (user.equals(claim.getOpenedBy())) {
            throw new ClaimApprovalForbiddenException(id, user, "whoever opened a claim cannot approve it");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        requireProof(sheetId, person, claim);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String due = settle(sheetId, person, claim);
        claim.setStatus(ClaimStatus.SETTLED);
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_APPROVED", user, person, saved) + numberOf(saved.getNumber()) + due);
        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward rejects a PENDING claim with a reason: it goes back to OPEN, bound again by its person's last statement
     * if that statement included it.
     */
    @Transactional
    public Claim reject(String sheetId, String user, Long id, String reason) {
        Claim claim = pendingForDecision(sheetId, user, id, ClaimStatus.OPEN);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setStatus(ClaimStatus.OPEN);
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_REJECTED", user, person, saved) + numberOf(saved.getNumber())
                + " reason=" + reason);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A user whose role may reassign moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
     * loses any figure a statement bound it to (live again until its new person's next statement), and is listed as
     * its new person's newest claim. Refused for a SETTLED or VOID claim, its own person, a closed period, a new person
     * retired before its date, or a user whose role may not reassign.
     */
    @Transactional
    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (!roles.may(sheetId, user, "reassign")) {
            throw new ClaimReassignForbiddenException(id, user);
        }
        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
            throw new ClaimReassignException(id, "it is " + claim.getStatus());
        }
        if (claim.getPersonId().equals(toPersonId)) {
            throw new ClaimReassignException(id, "it is already that person's");
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
        to.requireClaimable(claim.getDate());
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setPersonId(to.getId());
        claim.setStated(false, null);
        claim.setListed(sheets.nextListed(sheetId));
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
                + " from=" + from.getName() + " to=" + to.getName());
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts in
     * no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim not OPEN, a
     * date not after today, or a closed period.
     */
    @Transactional
    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ClaimDeferException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be deferred");
        }
        LocalDate today = sheets.today(sheetId);
        if (until == null || !until.isAfter(today)) {
            throw new ClaimDeferException(id, "it can only be deferred to a date after " + today);
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setDeferredUntil(until);
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_DEFERRED", user, person, saved) + numberOf(saved.getNumber())
                + " until=" + until);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
     * bound by no statement (today's rates and grades with its late charge as of today, raised to the floor). Refused for any other
     * status, a closed period, or a user not a steward.
     */
    @Transactional
    public Claim resettle(String sheetId, String user, Long id) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimResettleForbiddenException(id, user);
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
        }
        periods.requireOpen(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        String old = shownDue(sheetId, person, claim);
        BigDecimal figure = dueOf(sheetId, person, claim);
        Sheet sheet = settings.get(sheetId);
        claim.setSettledDue(claim.isCorrection() ? figure
                : sheet.floored(sheet.withLateCharge(figure, true, overdueBy(sheet, person, claim), claim.getDate()), claim.getDate()));
        Claim saved = claims.saveAndFlush(claim);
        log(sheetId, user, person, saved);
        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed, and so its period and number, and a
     * figure its statement bound it to stays bound. Refused for any other status, a date after its person's retirement,
     * a claim due by a date in a closed period, or a user not a steward.
     */
    @Transactional
    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ClaimRedateForbiddenException(id, user);
        }
        if (!claim.getStatus().isOpen()) {
            throw new ClaimRedateException(id, "it is " + claim.getStatus()
                    + ", only an OPEN or PENDING claim can be re-dated");
        }
        LocalDate old = claim.getDate();
        // Its due-by, and so its period, stays as fixed.
        periods.requireOpen(sheetId, claim.getDueBy());
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
        person.requireClaimable(date);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setDate(date);
        if (!claim.isCorrection()) {
            claim.setRoundingDate(date);
        }
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_REDATED", user, person, saved) + numberOf(saved.getNumber())
                + " old=" + old + " new=" + date);
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

