239	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
240	        // Due by its person's terms on its date in business days after it, skipping the sheet's holidays now, fixed from now on;
241	        // its period is the one of its due-by.
242	        LocalDate dueBy = dueByOf(sheetId, person, dated);
243	        periods.requireOpen(sheetId, dueBy);
244	        person.requireClaimable(dated);
245	        LocalDate correctedDate = requireCorrection(sheetId, personId, amount, corrects);
246	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note));
247	        claim.setCorrects(corrects);
248	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
249	        claim.setDueBy(dueBy);
250	        // Taking the next list place locks the sheet, so two adds of the same reference do not both pass the check.
251	        claim.setListed(sheets.nextListed(sheetId));
252	        String reference = refOf(ref);
253	        if (reference != null && claims.existsBySheetIdAndRefIgnoreCase(sheetId, reference)) {
254	            throw new ClaimRefException(reference);
255	        }
256	        claim.setRef(reference);
257	        claim.setTags(tagged(sheetId, tagText));
258	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
259	        Claim saved = claims.saveAndFlush(claim);
260	        log(sheetId, user, person, saved);
261	        audit.recordOnCommit(record("CLAIM_ADDED", user, person, saved)
262	                + (saved.getRef() == null ? "" : " ref=" + saved.getRef())
263	                + (saved.getTags() == null ? "" : " tags=" + saved.getTags()));
264	        if (saved.isLateEntry()) {
265	            audit.recordOnCommit(record("LATE_ENTRY", user, person, saved));
266	        }
267	        rollup.recordChanges(sheetId, user, before);
268	        return saved;
269	    }
