271	    @Transactional
272	    public Claim update(String sheetId, String user, Long id, BigDecimal amount, LocalDate date, String note,
273	            String corrects, String ref, String tagText) {
274	        RollupService.Snapshot before = rollup.snapshot(sheetId);
275	        Claim claim = claims.findForUpdate(id, sheetId)
276	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
277	        // Only a DRAFT can be edited: an OPEN claim is changed by voiding it and adding a new one.
278	        if (claim.getStatus() != ClaimStatus.DRAFT) {
279	            throw new ClaimNotEditableException(id, claim.getStatus());
280	        }
281	        // Not while another user has its editor open.
282	        if (claim.isLockedAgainst(user)) {
283	            throw new ClaimLockedException(id, claim.getLockedBy());
284	        }
285	        LocalDate dated = dateOr(sheetId, date);
286	        // Its due-by, and so its period, stays as fixed when it was added.
287	        periods.requireOpen(sheetId, claim.getDueBy());
288	        people.findByIdAndSheetId(claim.getPersonId(), sheetId)
289	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()))
290	                .requireClaimable(dated);
291	        LocalDate correctedDate = requireCorrection(sheetId, claim.getPersonId(), amount, corrects);
292	        String reference = refOf(ref);
293	        if (reference != null && claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, reference, id)) {
294	            throw new ClaimRefException(reference);
295	        }
296	        claim.setRef(reference);
297	        claim.setTags(tagged(sheetId, tagText));
298	        claim.setAmount(amount);
299	        claim.setCorrects(corrects);
300	        claim.setDate(dated);
301	        claim.setRoundingDate(correctedDate != null ? correctedDate : dated);
302	        claim.setNote(noteOf(note));
303	        // Saving the editor releases its lock.
304	        claim.setLockedBy(null);
305	        Claim saved = claims.saveAndFlush(claim);
306	        Person person = people.findByIdAndSheetId(saved.getPersonId(), sheetId)
307	                .orElseThrow(() -> new PersonNotFoundException(sheetId, saved.getPersonId()));
308	        audit.recordOnCommit(record("CLAIM_EDITED", user, person, saved));
309	        rollup.recordChanges(sheetId, user, before);
310	        return saved;
311	    }
