313	    /**
314	     * Open the claim's editor for the user, locking the claim against other users' edits until it is saved or
315	     * cancelled, or the sheet's today changes. Refused, taking no lock, for a claim that cannot be edited: not a DRAFT,
316	     * due by a date in a closed period, or locked by another user. The user's own lock is taken again.
317	     */
318	    @Transactional
319	    public Claim lock(String sheetId, String user, Long id) {
