345	    /**
346	     * Move a claim to another status, if its current one allows it; refused otherwise. A clerk settling a claim whose
347	     * due is above the clerk limit sends it to PENDING instead, for a steward to approve or reject.
348	     */
349	    @Transactional
350	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status) {
351	        return changeStatus(sheetId, user, id, status, null);
