354	    /**
355	     * Move a claim to another status, as {@link #changeStatus(String, String, Long, ClaimStatus)}. While the sheet's
356	     * list of void reasons is not empty, a void needs a reason from it; the claim keeps the reason it was voided with.
357	     */
358	    @Transactional
359	    public Claim changeStatus(String sheetId, String user, Long id, ClaimStatus status, String voidReason) {
360	        Claim claim = claims.findForUpdate(id, sheetId)
361	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
362	        boolean voidsSettled = status == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
363	        if (!voidsSettled && (!claim.getStatus().canMoveTo(status) || status == ClaimStatus.PENDING)) {
364	            throw new ClaimStatusException(id, claim.getStatus(), status);
365	        }
366	        // The sheet's permission matrix decides which roles may open, settle or void.
367	        String action = switch (status) {
368	            case OPEN -> "open";
369	            case SETTLED -> "settle";
370	            case VOID -> "void";
371	            case DRAFT, PENDING -> throw new ClaimStatusException(id, claim.getStatus(), status);
372	        };
373	        if (!roles.may(sheetId, user, action)) {
374	            throw new ClaimActionForbiddenException(id, user, action);
375	        }
376	        if (voidsSettled) {
377	            requireSettledVoidable(sheetId, user, claim);
378	        }
379	        periods.requireOpen(sheetId, claim.getDueBy());
380	        String reason = status == ClaimStatus.VOID ? requireVoidReason(sheetId, id, voidReason) : null;
381	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
382	        if (status == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
383	            throw new ClaimDeferException(id, "it is deferred until " + claim.getDeferredUntil());
384	        }
385	        // Four eyes: whoever opened a claim cannot also settle it.
386	        if (status == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
387	            throw new ClaimSettledByOpenerException(id, user);
388	        }
389	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
390	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
391	        if (status == ClaimStatus.SETTLED) {
392	            requireProof(sheetId, person, claim);
393	        }
394	        if (status == ClaimStatus.OPEN) {
395	            requireNote(sheetId, person, claim);
396	        }
397	        // A clerk settles only a claim whose due (the one its statement bound it to, else worked out from the rate)
398	        // is at or below the clerk limit; one above it goes to PENDING. A due of n/a is within any limit.
399	        if (status == ClaimStatus.SETTLED && roles.roleOf(sheetId, user) == Role.CLERK) {
400	            BigDecimal limit = settings.get(sheetId).getClerkLimit();
401	            BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
402	            if (limit != null && due != null && due.compareTo(limit) > 0) {
403	                status = ClaimStatus.PENDING;
404	            }
405	        }
406	        RollupService.Snapshot before = rollup.snapshot(sheetId);
407	        String due = status == ClaimStatus.SETTLED ? settle(sheetId, person, claim)
408	                : voidsSettled ? " reversed=" + shownDue(sheetId, person, claim) : "";
409	        claim.setStatus(status);
410	        if (status == ClaimStatus.VOID) {
411	            claim.setVoidReason(reason);
412	        }
413	        // A voided claim keeps its number (never reused), and the CLAIM_VOIDED record carries it.
414	        String number = claim.getNumber();
415	        if (status == ClaimStatus.OPEN) {
416	            number = nextNumber(sheetId, claim.getDueBy());
417	            claim.setNumber(number);
418	            claim.setOpenedBy(user);
419	        }
420	        Claim saved = claims.saveAndFlush(claim);
421	        log(sheetId, user, person, saved);
422	        String event = switch (status) {
423	            case OPEN -> "CLAIM_OPENED";
424	            case PENDING -> "CLAIM_PENDING";
425	            case SETTLED -> "CLAIM_SETTLED";
426	            case VOID -> "CLAIM_VOIDED";
427	            case DRAFT -> throw new IllegalStateException();
428	        };
429	        audit.recordOnCommit(record(event, user, person, saved) + numberOf(number) + due
430	                + (reason == null ? "" : " reason=" + reason));
431	        if (status == ClaimStatus.SETTLED) {
432	            watches.notifyWatchers(sheetId, user, person, number);
433	        }
434	        rollup.recordChanges(sheetId, user, before);
435	        return saved;
436	    }
