438	    /**
439	     * The reason a claim is voided with: none while the sheet's list of void reasons is empty, else the one given,
440	     * which must be on the list.
441	     */
442	    private String requireVoidReason(String sheetId, Long id, String given) {
443	        List<String> listed = voidReasons.list(sheetId).stream().map(VoidReason::getReason).toList();
444	        if (listed.isEmpty()) {
445	            return null;
446	        }
447	        String reason = given == null ? "" : given.trim();
448	        if (reason.isEmpty()) {
449	            throw new ClaimVoidReasonException(id, "choose a reason from the sheet's void reasons");
450	        }
451	        if (!listed.contains(reason)) {
452	            throw new ClaimVoidReasonException(id, reason + " is not one of the sheet's void reasons");
453	        }
454	        return reason;
455	    }
