500	    /**
501	     * A user whose role may reassign moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
502	     * loses any figure a statement bound it to (live again until its new person's next statement), and is listed as
503	     * its new person's newest claim. Refused for a SETTLED or VOID claim, its own person, a closed period, a new person
504	     * retired before its date, or a user whose role may not reassign.
505	     */
506	    @Transactional
507	    public Claim reassign(String sheetId, String user, Long id, Long toPersonId) {
508	        Claim claim = claims.findForUpdate(id, sheetId)
509	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
510	        if (!roles.may(sheetId, user, "reassign")) {
511	            throw new ClaimReassignForbiddenException(id, user);
512	        }
513	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
514	            throw new ClaimReassignException(id, "it is " + claim.getStatus());
515	        }
516	        if (claim.getPersonId().equals(toPersonId)) {
517	            throw new ClaimReassignException(id, "it is already that person's");
518	        }
519	        periods.requireOpen(sheetId, claim.getDueBy());
520	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
521	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
522	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
523	                .orElseThrow(() -> new PersonNotFoundException(sheetId, toPersonId));
524	        to.requireClaimable(claim.getDate());
525	        RollupService.Snapshot before = rollup.snapshot(sheetId);
526	        claim.setPersonId(to.getId());
527	        claim.setStated(false, null);
528	        claim.setListed(sheets.nextListed(sheetId));
529	        Claim saved = claims.saveAndFlush(claim);
530	        audit.recordOnCommit(record("CLAIM_REASSIGNED", user, to, saved) + numberOf(saved.getNumber())
531	                + " from=" + from.getName() + " to=" + to.getName());
532	        rollup.recordChanges(sheetId, user, before);
533	        return saved;
534	    }
