536	    /**
537	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim counts in
538	     * no total, is not overdue, cannot be settled and is left unbound by a statement. Refused for a claim not OPEN, a
539	     * date not after today, or a closed period.
540	     */
541	    @Transactional
542	    public Claim defer(String sheetId, String user, Long id, LocalDate until) {
543	        Claim claim = claims.findForUpdate(id, sheetId)
544	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
545	        if (claim.getStatus() != ClaimStatus.OPEN) {
546	            throw new ClaimDeferException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be deferred");
547	        }
548	        LocalDate today = sheets.today(sheetId);
549	        if (until == null || !until.isAfter(today)) {
550	            throw new ClaimDeferException(id, "it can only be deferred to a date after " + today);
551	        }
552	        periods.requireOpen(sheetId, claim.getDueBy());
553	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
554	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
555	        RollupService.Snapshot before = rollup.snapshot(sheetId);
556	        claim.setDeferredUntil(until);
557	        Claim saved = claims.saveAndFlush(claim);
558	        audit.recordOnCommit(record("CLAIM_DEFERRED", user, person, saved) + numberOf(saved.getNumber())
559	                + " until=" + until);
560	        rollup.recordChanges(sheetId, user, before);
561	        return saved;
562	    }
