564	    /**
565	     * A steward re-settles a SETTLED claim: its due is frozen again at the figure it would have today as an OPEN claim
566	     * bound by no statement (today's rates and grades with its late charge as of today, raised to the floor). Refused for any other
567	     * status, a closed period, or a user not a steward.
568	     */
569	    @Transactional
570	    public Claim resettle(String sheetId, String user, Long id) {
571	        Claim claim = claims.findForUpdate(id, sheetId)
572	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
573	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
574	            throw new ClaimResettleForbiddenException(id, user);
575	        }
576	        if (claim.getStatus() != ClaimStatus.SETTLED) {
577	            throw new ClaimStatusException(id, claim.getStatus(), ClaimStatus.SETTLED);
578	        }
579	        periods.requireOpen(sheetId, claim.getDueBy());
580	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
581	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
582	        RollupService.Snapshot before = rollup.snapshot(sheetId);
583	        String old = shownDue(sheetId, person, claim);
584	        BigDecimal figure = dueOf(sheetId, person, claim);
585	        Sheet sheet = settings.get(sheetId);
586	        claim.setSettledDue(claim.isCorrection() ? figure
587	                : sheet.floored(sheet.withLateCharge(figure, true, overdueBy(sheet, person, claim), claim.getDate()), claim.getDate()));
588	        Claim saved = claims.saveAndFlush(claim);
589	        log(sheetId, user, person, saved);
590	        audit.recordOnCommit(record("CLAIM_RESETTLED", user, person, saved) + numberOf(saved.getNumber())
591	                + " old=" + old + " new=" + shownDue(sheetId, person, saved));
592	        watches.notifyWatchers(sheetId, user, person, saved.getNumber());
593	        rollup.recordChanges(sheetId, user, before);
594	        return saved;
595	    }
