597	    /**
598	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed, and so its period and number, and a
599	     * figure its statement bound it to stays bound. Refused for any other status, a date after its person's retirement,
600	     * a claim due by a date in a closed period, or a user not a steward.
601	     */
602	    @Transactional
603	    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
604	        Claim claim = claims.findForUpdate(id, sheetId)
605	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
606	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
607	            throw new ClaimRedateForbiddenException(id, user);
608	        }
609	        if (!claim.getStatus().isOpen()) {
610	            throw new ClaimRedateException(id, "it is " + claim.getStatus()
611	                    + ", only an OPEN or PENDING claim can be re-dated");
612	        }
613	        LocalDate old = claim.getDate();
614	        // Its due-by, and so its period, stays as fixed.
615	        periods.requireOpen(sheetId, claim.getDueBy());
616	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
617	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
618	        person.requireClaimable(date);
619	        RollupService.Snapshot before = rollup.snapshot(sheetId);
620	        claim.setDate(date);
621	        if (!claim.isCorrection()) {
622	            claim.setRoundingDate(date);
623	        }
624	        Claim saved = claims.saveAndFlush(claim);
625	        audit.recordOnCommit(record("CLAIM_REDATED", user, person, saved) + numberOf(saved.getNumber())
626	                + " old=" + old + " new=" + date);
627	        rollup.recordChanges(sheetId, user, before);
628	        return saved;
629	    }
