631	    /**
632	     * Split an amount (more than 0.00 and less than its own) off an OPEN claim not deferred. The claim keeps the rest
633	     * and loses any figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the
634	     * same date and note, the next number, opened by the user, due by its date plus the terms in force on that date,
635	     * names the claim's number as the one it was split from. Refused for any other status, a claim due by a date in a
636	     * closed period (the new claim's own due-by is not weighed), or a user
637	     * whose role may not open a claim.
638	     */
639	    @Transactional
640	    public Claim split(String sheetId, String user, Long id, BigDecimal amount) {
641	        Claim claim = claims.findForUpdate(id, sheetId)
642	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
643	        if (!roles.may(sheetId, user, "open")) {
644	            throw new ClaimActionForbiddenException(id, user, "open");
645	        }
646	        if (claim.getStatus() != ClaimStatus.OPEN) {
647	            throw new ClaimSplitException(id, "it is " + claim.getStatus() + ", only an OPEN claim can be split");
648	        }
649	        if (claim.isDeferredOn(sheets.today(sheetId))) {
650	            throw new ClaimSplitException(id, "it is deferred until " + claim.getDeferredUntil());
651	        }
652	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
653	            throw new ClaimSplitException(id, "the amount split off must be more than 0.00 and less than "
654	                    + claim.getAmount().toPlainString());
655	        }
656	        periods.requireOpen(sheetId, claim.getDueBy());
657	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
658	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
659	        RollupService.Snapshot before = rollup.snapshot(sheetId);
660	        claim.setAmount(claim.getAmount().subtract(amount));
661	        claim.setStated(false, null);
662	        Claim kept = claims.saveAndFlush(claim);
663	        Claim part = new Claim(sheetId, kept.getPersonId(), amount, kept.getDate(), kept.getNote());
664	        part.setRoundingDate(kept.getRoundingDate());
665	        part.setDueBy(dueByOf(sheetId, person, kept.getDate()));
666	        part.setListed(sheets.nextListed(sheetId));
667	        part.setLateEntry(periods.softClosedOn(sheetId, part.getDueBy()));
668	        part.setStatus(ClaimStatus.OPEN);
669	        String number = nextNumber(sheetId, part.getDueBy());
670	        part.setNumber(number);
671	        part.setOpenedBy(user);
672	        part.setSplitFrom(kept.getNumber());
673	        part.setTags(kept.getTags());
674	        Claim saved = claims.saveAndFlush(part);
675	        log(sheetId, user, person, saved);
676	        audit.recordOnCommit(record("CLAIM_SPLIT", user, person, kept) + numberOf(kept.getNumber())
677	                + " into=" + number);
678	        audit.recordOnCommit(record("CLAIM_OPENED", user, person, saved) + numberOf(number));
679	        rollup.recordChanges(sheetId, user, before);
680	        return saved;
681	    }
