683	    /**
684	     * Add a proof to a claim, raising its proofs count by one. Refused for a SETTLED or VOID claim, or a closed period.
685	     */
686	    @Transactional
687	    public Claim addProof(String sheetId, String user, Long id) {
688	        Claim claim = claims.findForUpdate(id, sheetId)
689	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
690	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
691	            throw new ClaimProofException(id, "it is " + claim.getStatus() + ", a proof cannot be added");
692	        }
693	        periods.requireOpen(sheetId, claim.getDueBy());
694	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
695	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
696	        claim.addProof();
697	        Claim saved = claims.saveAndFlush(claim);
698	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", user, person, saved) + numberOf(saved.getNumber())
699	                + " proofs=" + saved.getProofs());
700	        return saved;
701	    }
702	
703	    /**
704	     * Remind an OPEN or PENDING claim: REMIND is written and the claim's reminded date becomes the sheet's today.
705	     * Refused for any other status, and for a claim already reminded on the sheet's today.
706	     */
707	    @Transactional
708	    public Claim remind(String sheetId, String user, Long id) {
709	        Claim claim = claims.findForUpdate(id, sheetId)
710	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
711	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
712	            throw new ClaimRemindException(id, "it is " + claim.getStatus()
713	                    + ", only an OPEN or PENDING claim can be reminded");
714	        }
715	        LocalDate today = sheets.today(sheetId);
716	        if (today.equals(claim.getRemindedOn())) {
717	            throw new ClaimRemindException(id, "it was already reminded on " + today);
718	        }
719	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
720	                .orElseThrow(() -> new PersonNotFoundException(sheetId, claim.getPersonId()));
721	        claim.setRemindedOn(today);
722	        Claim saved = claims.saveAndFlush(claim);
723	        audit.recordOnCommit(record("REMIND", user, person, saved) + numberOf(saved.getNumber()));
724	        return saved;
725	    }
