727	    /**
728	     * A claim whose due (as the clerk limit weighs it) is above the proof threshold in force on its date cannot be
729	     * settled or approved while it has no proof; refused then. A due of n/a is within any threshold.
730	     */
731	    private void requireProof(String sheetId, Person person, Claim claim) {
732	        BigDecimal threshold = settings.get(sheetId).proofThresholdOn(claim.getDate());
733	        if (threshold == null || claim.getProofs() > 0) {
734	            return;
735	        }
736	        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
737	        if (due != null && due.compareTo(threshold) > 0) {
738	            throw new ClaimProofException(claim.getId(), "its due " + due.toPlainString()
739	                    + " is above the proof threshold " + threshold.toPlainString() + " and it has no proof");
740	        }
741	    }
742	
743	    /**
744	     * A claim whose due is above the note threshold in force on its date cannot be opened while its note is empty;
745	     * refused then. A due of n/a is within any threshold.
746	     */
747	    private void requireNote(String sheetId, Person person, Claim claim) {
748	        BigDecimal threshold = settings.get(sheetId).noteThresholdOn(claim.getDate());
749	        if (threshold == null || !noteOf(claim.getNote()).isEmpty()) {
750	            return;
751	        }
752	        BigDecimal due = liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
753	        if (due != null && due.compareTo(threshold) > 0) {
754	            throw new ClaimNoteException(claim.getId(), "its due " + due.toPlainString()
755	                    + " is above the note threshold " + threshold.toPlainString() + " and its note is empty");
756	        }
757	    }
758	
759	    /**
760	     * Only a steward voids a SETTLED claim, and only within the days allowed after its settlement (the date of the last
761	     * SETTLED line of its status log) by the sheet's today; refused otherwise.
762	     */
763	    private void requireSettledVoidable(String sheetId, String user, Claim claim) {
764	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
765	            throw new ClaimActionForbiddenException(claim.getId(), user, "void a settled claim");
766	        }
767	        LocalDate settledOn = logOf(claim).stream()
768	                .filter(l -> l.getStatus() == ClaimStatus.SETTLED)
769	                .map(ClaimLog::getDate)
770	                .reduce((first, last) -> last)
771	                .orElse(null);
772	        LocalDate today = sheets.today(sheetId);
773	        if (settledOn == null || today.isAfter(settledOn.plusDays(SETTLED_VOID_DAYS))) {
774	            throw new ClaimVoidException(claim.getId(), "a settled claim can only be voided within "
775	                    + SETTLED_VOID_DAYS + " days of its settlement on " + settledOn);
776	        }
777	    }
778	
779	    /** The PENDING claim a steward decides; refused for any other status, a closed period, or a user not a steward. */
780	    private Claim pendingForDecision(String sheetId, String user, Long id, ClaimStatus to) {
781	        Claim claim = claims.findForUpdate(id, sheetId)
782	                .orElseThrow(() -> new ClaimNotFoundException(sheetId, id));
783	        if (claim.getStatus() != ClaimStatus.PENDING) {
784	            throw new ClaimStatusException(id, claim.getStatus(), to);
785	        }
786	        periods.requireOpen(sheetId, claim.getDueBy());
787	        if (roles.roleOf(sheetId, user) != Role.STEWARD) {
788	            throw new ClaimApprovalForbiddenException(id, user, "only a steward approves or rejects a pending claim");
789	        }
790	        return claim;
791	    }
792	
793	    /**
794	     * Fixes the due the claim shows as it settles: its figure (the one its statement binds it to, else worked out from
795	     * the rate on the claim's date) with its late charge, raised to the floor on its date, frozen in (a correction
796	     * freezes its bare figure); with no figure it stays live. Gives the due at the
797	     * end of its audit record.
798	     */
799	    private String settle(String sheetId, Person person, Claim claim) {
800	        BigDecimal figure = figureOf(sheetId, person, claim);
801	        Sheet sheet = settings.get(sheetId);
802	        BigDecimal settledDue = figure == null || claim.isCorrection() ? figure
803	                : sheet.floored(figure.add(sheet.lateCharge(figure, overdueBy(sheet, person, claim), claim.getDate())), claim.getDate());
804	        claim.setSettledDue(settledDue);
805	        return " due=" + (settledDue == null ? "n/a" : settledDue.toPlainString());
806	    }
807	
808	    /** Logs the claim's status now: who changed it, the sheet's today, and its due as computed at this moment. */
809	    private void log(String sheetId, String user, Person person, Claim claim) {
810	        logs.save(new ClaimLog(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
811	                shownDue(sheetId, person, claim)));
812	    }
813	
814	    /**
815	     * The claim's due as shown: the one fixed when it was settled, else its live due; two decimals, or n/a.
816	     */
817	    private String shownDue(String sheetId, Person person, Claim claim) {
818	        BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
819	                : liveDue(sheetId, person, claim, figureOf(sheetId, person, claim));
820	        return due == null ? "n/a" : due.setScale(2, RoundingMode.HALF_EVEN).toPlainString();
821	    }
822	
823	    /** The figure under the claim's due: the one its statement binds it to now, else worked out from the rate. */
824	    private BigDecimal figureOf(String sheetId, Person person, Claim claim) {
825	        return claim.isBound() ? claim.getStatedDue() : dueOf(sheetId, person, claim);
826	    }
827	
828	    /**
829	     * A negative amount (a correction) must name, by number, a SETTLED claim of the same person; any other amount
830	     * names none. Refused otherwise. Gives the date of the claim a correction corrects (it rounds by that date), null
831	     * for any other claim.
832	     */
833	    private LocalDate requireCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
834	        if (amount.signum() >= 0) {
835	            if (corrects != null) {
836	                throw new ClaimCorrectionException("Only a correction (a negative amount) corrects a claim");
837	            }
838	            return null;
839	        }
840	        if (corrects == null) {
841	            throw new ClaimCorrectionException("A negative amount must name the settled claim it corrects");
842	        }
843	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
844	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED)
845	                .map(Claim::getDate)
846	                .orElseThrow(() -> new ClaimCorrectionException(
847	                        "Claim " + corrects + " is not a settled claim of the same person"));
848	    }
849	
850	    /**
851	     * The claim's amount at the rate its person's grade has on its date, two decimals rounded as the sheet's policy
852	     * date has the claim round (the rate figure, with no floor); null (n/a) with no rate.
853	     */
854	    private BigDecimal dueOf(String sheetId, Person person, Claim claim) {
855	        Sheet sheet = settings.get(sheetId);
856	        return rates.rateOn(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
857	                .map(Rate::getPct)
858	                .map(pct -> sheet.rateStep(claim.getAmount(), pct, claim.getRoundingDate()))
859	                .orElse(null);
860	    }
861	
862	    /**
863	     * The live due on a figure: the greater of the floor in force on the claim's date and the figure with the late
864	     * charge of an OPEN or PENDING claim overdue on the sheet's today added on top (no late charge on a claim deferred
865	     * on the sheet's today; a correction has neither floor nor late charge); null (n/a) stays null.
866	     */
867	    private BigDecimal liveDue(String sheetId, Person person, Claim claim, BigDecimal figure) {
868	        Sheet sheet = settings.get(sheetId);
869	        if (claim.isCorrection()) {
870	            return figure;
871	        }
872	        return sheet.floored(sheet.withLateCharge(figure, claim.getStatus().isOpen()
873	                && !claim.isDeferredOn(sheet.getToday()), overdueBy(sheet, person, claim), claim.getDate()), claim.getDate());
874	    }
875	
876	    /** The day the claim goes overdue after: its due-by plus the grace days its person's grade has on its date. */
877	    private static LocalDate overdueBy(Sheet sheet, Person person, Claim claim) {
878	        return sheet.overdueBy(claim.getDueBy(), person.gradeOn(claim.getDate()), claim.getDate());
879	    }
880	
881	    /** The amount as shown (two decimals) and the date as yyyy-mm-dd. */
882	    private static String record(String event, String user, Person person, Claim claim) {
883	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
884	                + " amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
885	                + " date=" + claim.getDate();
886	    }
887	
888	    /** The claim's number at the end of an audit record, or nothing when it has none. */
889	    private static String numberOf(String number) {
890	        return number == null ? "" : " number=" + number;
891	    }
892	
893	    /**
894	     * The number a claim due by the date gets when opened: while the sheet numbers by period, the next in its
895	     * period's own sequence (X for no period); otherwise the next sheet-wide number.
896	     */
897	    private String nextNumber(String sheetId, LocalDate date) {
898	        if (settings.get(sheetId).numbersByPeriod()) {
899	            return sheets.nextSequenceNumber(sheetId, periods.nameOn(sheetId, date).orElse("X"));
900	        }
901	        return String.valueOf(sheets.nextClaimNumber(sheetId));
902	    }
903	
904	    /** The person's terms on the date counted as business days after it, skipping the sheet's holidays. */
905	    private LocalDate dueByOf(String sheetId, Person person, LocalDate date) {
906	        return holidays.businessDaysAfter(sheetId, date, termsFor(sheetId, person, date));
907	    }
908	
909	    /** The terms of the person on the date: their own, else their grade's on that date, else the sheet's then. */
910	
911	    private int termsFor(String sheetId, Person person, LocalDate date) {
912	        return person.getTerms() != null ? person.getTerms()
913	                : settings.termsFor(sheetId, person.gradeOn(date), date);
914	    }
915	
916	    private LocalDate dateOr(String sheetId, LocalDate date) {
917	        return date != null ? date : sheets.today(sheetId);
918	    }
919	
920	    private static String noteOf(String note) {
921	        return note == null ? "" : note.trim();
922	    }
923	
924	    /** The reference with surrounding spaces removed; null for a blank one (no reference). */
925	    /**
926	     * The tags of comma separated text, each trimmed and lower-cased, without repeats, sorted and joined by commas
927	     * (null when there are none), each noted as used on the sheet.
928	     */
929	    private String tagged(String sheetId, String text) {
