1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, OnInit, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
3	import { firstValueFrom } from 'rxjs';
4	import { Session } from '../../core/session';
5	import { VoidReasons } from '../../core/void-reasons';
6	import { Period, periodOn } from '../periods/periods';
7	import { Rate, Rounding, dueOf, floored, percentOf, rateOn, sumDues } from '../rates/rates';
8	
9	export interface Claim {
10	  id: number;
11	  personId: number;
12	  /** Two decimals, e.g. "2.50". */
13	  amount: string;
14	  /** yyyy-mm-dd */
15	  date: string;
16	  note: string;
17	  status: ClaimStatus;
18	  /** Given when the claim is opened; null for a DRAFT and once voided. */
19	  number: string | null;
20	  /** The due fixed when the claim was settled, two decimals; null when it has none and its due is live. */
21	  settledDue: string | null;
22	  /** The user who opened the claim; null for a DRAFT. That user cannot settle it. */
23	  openedBy: string | null;
24	  /** Whether the person's last statement bound the claim: it then shows the due it bound it to. */
25	  stated: boolean;
26	  /** The due the last statement bound the claim to, two decimals; null when unbound, or bound with none (n/a). */
27	  statedDue: string | null;
28	  /** The number of the SETTLED claim of the same person this claim corrects; null unless it is a correction. */
29	  corrects: string | null;
30	  /** The date (yyyy-mm-dd) that decides how its live figures round: its own, or a correction's corrected claim's. */
31	  roundingDate: string;
32	  /** Its place in its person's list: a claim with a later place is listed first (newest added, or last reassigned). */
33	  listed: number;
34	  /** The day (yyyy-mm-dd) the claim is due by, fixed when it was added from the terms of its person's grade on its date. */
35	  dueBy: string;
36	  /** Its status log, oldest first: one line per status it has had. */
37	  log: ClaimLogLine[];
38	  /** The date (yyyy-mm-dd) an OPEN claim is deferred until; null when it was never deferred. */
39	  deferredUntil: string | null;
40	  /** How many proofs the claim has: one above the proof threshold on its date cannot be settled or approved with none. */
41	  proofs: number;
42	  /** The number of the claim this one was split off; null unless it was split off another. */
43	  splitFrom: string | null;
44	  /** The user whose open editor locks the claim against other users' edits; null when not locked. */
45	  lockedBy: string | null;
46	  /** Whether the claim was added while the period its due-by falls in was soft-closed. */
47	  lateEntry: boolean;
48	  /** The last day (yyyy-mm-dd) a reminder was written for the claim; null when it was never reminded. */
49	  remindedOn: string | null;
50	  /** The claim's external reference, unique on the sheet regardless of case; null when it has none. */
51	  ref: string | null;
52	  /** The claim's tags: trimmed, lower-cased, without repeats, sorted and joined by commas; null when it has none. */
53	  tags: string | null;
54	  /** The reason the claim was voided with, from the sheet's list; null when none. */
55	  voidReason: string | null;
56	}
57	
58	/** A line of a claim's status log: the status, who changed it, the sheet's today then, and the due then (or n/a). */
59	export interface ClaimLogLine {
60	  status: ClaimStatus;
61	  by: string;
62	  /** yyyy-mm-dd */
63	  date: string;
64	  due: string;
65	}
66	
67	/** Claims as listed: the latest list place first. */
68	export function byListed(a: Claim, b: Claim): number {
69	  return b.listed - a.listed || b.id - a.id;
70	}
71	
72	/**
73	 * DRAFT when added, then OPEN, then SETTLED; a clerk settling above the clerk limit makes it PENDING until a steward
74	 * approves (SETTLED) or rejects it (OPEN). A DRAFT, OPEN or PENDING claim may be VOID, and a steward may void a
75	 * SETTLED one within 7 days of its settlement.
76	 */
77	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
78	
79	/** The claim's tags, sorted; none when it has none. */
80	export function tagsOf(claim: Claim): string[] {
81	  return claim.tags === null ? [] : claim.tags.split(',');
82	}
83	
84	/** Whether a claim is a correction (a negative amount): its due has no floor and no late charge. */
85	export function isCorrection(claim: Claim): boolean {
86	  return claim.amount.trim().startsWith('-') && /[1-9]/.test(claim.amount);
87	}
88	
89	/**
90	 * Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED ones do, but not one deferred on
91	 * the sheet's today.
92	 */
93	export function counts(claim: Claim, today: string | null): boolean {
94	  return (isOpen(claim) || claim.status === 'SETTLED') && !deferred(claim, today);
95	}
96	
97	/**
98	 * Whether the claim is deferred on the sheet's today: an OPEN claim deferred until a later date. It then counts in no
99	 * total, is not overdue, cannot be settled and is left unbound by a statement.
100	 */
101	export function deferred(claim: Claim, today: string | null): boolean {
102	  return claim.status === 'OPEN' && claim.deferredUntil !== null && today !== null && today < claim.deferredUntil;
103	}
104	
105	/**
106	 * The status the claim had at the end of the date, as its status log records it: its last line logged on or before
107	 * the date; null when it has lines but none by then (it was added later). With no log at all, its status now.
108	 */
109	export function statusOn(claim: Claim, date: string): ClaimStatus | null {
110	  if (claim.log.length === 0) return claim.status;
111	  let found: ClaimStatus | null = null;
112	  for (const line of claim.log) if (line.date <= date) found = line.status;
113	  return found;
114	}
115	
116	/** Whether a claim is handled as open: OPEN or PENDING. It goes overdue, bears the late charge, and a hold takes it out. */
117	export function isOpen(claim: Claim): boolean {
118	  return claim.status === 'OPEN' || claim.status === 'PENDING';
119	}
120	
121	/** Whether the claim's due follows its last statement now: a PENDING one shows its live figure while PENDING. */
122	export function bound(claim: Claim): boolean {
123	  return claim.stated && claim.status !== 'PENDING';
124	}
125	
126	/** One of a person's grades, from its from-date (yyyy-mm-dd); null from the beginning of time. */
127	export interface PersonGrade {
128	  grade: string;
129	  from: string | null;
130	}

